const property = items[0].json;
const formatted = {
  title: property.title,
  description: property.description,
  price: property.price,
  location: property.location,
  specs: property.specs,
  images: property.images,
  features: property.features,
  listingType: property.listingType,
  agent: property.agent,
};

items.json = [{ formatted }];
return items;

const formatted = items.json[0];
const accessToken = $const('LINKEDIN_ACCESS_TOKEN');
const personId = $const('LINKEDIN_PERSON_ID');

if (!accessToken || !personId) {
  throw new Error('LinkedIn Access Token or Person ID not configured');
}

const response = await fetch('https://api.linkedin.com/v2/ugcPosts', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
    'X-Restli-Protocol-Version': '2.0.0',
  },
  body: JSON.stringify({
    author: `urn:li:person:${personId}`,
    lifecycleState: 'PUBLISHED',
    specificContent: {
      'com.linkedin.ugc.ShareContent': {
        shareCommentary: {
          text: formatted.description,
        },
        shareMediaCategory: 'IMAGE',
        media: formatted.images.slice(0, 4).map(url => ({
          status: 'READY',
          originalUrl: url,
        })),
      },
    },
    visibility: {
      'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC',
    },
  }),
});

if (!response.ok) {
  throw new Error('Failed to post to LinkedIn');
}

const data = await response.json();
items.json = [{ postUrl: `https://linkedin.com/feed/update/urn:li:ugcPost:${data.id}` }];
return items;

const result = {
  platform: 'linkedin',
  success: true,
  postUrl: items.json[0].postUrl,
};
items.json = [result];
return items;

const result = items.json[0];
const webhookUrl = $const('WEBHOOK_URL');

if (webhookUrl) {
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ result, platform: 'linkedin' }),
  });
}

return items;
